function releaseClaim105(id,version){const q=ten.claims105?.find(q=>q.id===id);if(ten.role!=='super'||!super114()||!q||q.status!=='approved'||!q.quarantine||q.quarantineLifted||(q.version||0)!==Number(version))return toast(L105('Klaim berubah atau tidak tersedia.','The claim changed or is unavailable.'));atomic10(()=>{const w=ten.royalty107?.withdraw108;if(w){w.quarantined=(w.quarantined||[]).filter(x=>x!==q.member);w.version=(w.version||0)+1;}q.quarantineLifted=ten.now;(q.history??=[]).push({status:'released',note:'',at:ten.now,actor:state.user});q.version=(q.version||0)+1;ten.notifications.unshift({id:++ten.serial,member:q.applicant,key:'claim_released105',ref:q.id,at:ten.now});});save10();render();toast(L105('Karantina saldo dibuka. Baseline warisan disahkan.','Balance quarantine lifted. Legacy baseline approved.'));}
